# ==============================================================================
# llm-registry-auth (#3302): write the model registry's htpasswd.
#
# Zot (modules/llm/registry/config.json) lets anonymous clients READ and only
# the `llm-manager` identity write or delete. This one-shot runs before every
# registry start and derives that identity's bcrypt line from
# LLM_REGISTRY_WRITE_PASSWORD (generated by `rzfz init` / `rzfz upgrade`), so
# the file can never drift from .env. It runs in the stack's own Caddy image
# (`caddy hash-password`, no network); Zot's image is distroless.
#
# The password comes from a compose secret file (#3337: never the container's
# environment, so `docker inspect` does not show it), is deleted from the
# container as soon as it is read, and goes to caddy on stdin, never in an
# argument list. An EMPTY password does not stop the registry: an unusable
# random password is hashed instead, so reads keep working and every write is
# refused until the credential exists.
#
# bcrypt cost 4: the password is a 64-hex-digit random secret, so a higher cost
# adds no protection, while Zot checks it on every authenticated request (a
# model push is hundreds of 64 MiB chunks).
# ==============================================================================
set -eu
# busybox ash (the container) knows pipefail; a test host's dash does not
if (set -o pipefail) 2>/dev/null; then set -o pipefail; fi

auth_dir="${RZFZ_AUTH_DIR:-/auth}"
user="llm-manager"
pw_file="${RZFZ_REGISTRY_PW_FILE:-/run/secrets/llm_registry_write_password}"
pw=""
if [ -f "$pw_file" ]; then
    pw="$(cat "$pw_file")"
    # #3337: gone before anything else runs; the exited container keeps no copy
    rm -f "$pw_file"
    if [ -e "$pw_file" ]; then
        echo "[llm-registry-auth] could not delete the credential file after reading it" >&2
        exit 1
    fi
fi

if [ -z "$pw" ]; then
    echo "[llm-registry-auth] LLM_REGISTRY_WRITE_PASSWORD is empty: nobody can write to the model registry; reads still work. 'rzfz upgrade' generates it." >&2
    pw="$(od -An -N32 -tx1 /dev/urandom | tr -d ' \n')"
fi
nl='
'
cr="$(printf '\r')"
case "$pw" in
    *"$nl"* | *"$cr"*)
        echo "[llm-registry-auth] LLM_REGISTRY_WRITE_PASSWORD contains a line break and cannot be hashed" >&2
        exit 1 ;;
esac

hash="$(printf '%s\n' "$pw" | caddy hash-password --algorithm bcrypt --bcrypt-cost 4 | tail -n 1)"
case "$hash" in
    '$2'[aby]'$'*) ;;
    *) echo "[llm-registry-auth] could not hash the registry credential ('caddy hash-password' failed; its own error is above)" >&2
       exit 1 ;;
esac

umask 022
printf '%s:%s\n' "$user" "$hash" > "$auth_dir/htpasswd.tmp"
chmod 0644 "$auth_dir/htpasswd.tmp"
mv -f "$auth_dir/htpasswd.tmp" "$auth_dir/htpasswd"
echo "[llm-registry-auth] htpasswd written for '$user'"
